samping jika ada, atau tulis Tidak ada.","placeholder":"","required":true,"isActive":true,"choices":[],"colSpan":"full","disabled":false}],"repeatableGroup":"contraception"},{"id":"closing","title":"Selesai","description":"Terima kasih. Setelah form dikirim, petugas akan memeriksa dan melengkapi data rekam medis.","fields":[]}]}'::jsonb
