INSERT INTO clinical_intake_forms (code, name, description, icon_name, is_active, schema)
VALUES (
  'immunization',
  'imunisasi',
  'Form pendaftaran imunisasi anak mencakup identitas si kecil, orang tua, riwayat vaksinasi, dan riwayat alergi.',
  'shield-plus',
  true,
  '{"version":1,"title":"Form Pendaftaran Imunisasi Anak - Amanah Health Care","description":"Form pendaftaran ini diisi oleh orang tua/wali sebelum kunjungan imunisasi anak.","steps":[{"id":"childIdentity","title":"Data Identitas Anak","description":"Isi data identitas anak sesuai KK atau kartu identitas anak.","fields":[{"id":"childName","type":"TEXT","component":"text-input","title":"Nama lengkap anak","label":"Nama anak","helpText":"","placeholder":"Masukkan nama anak","required":true,"isActive":true,"choices":[],"colSpan":1,"disabled":false},{"id":"childNik","type":"TEXT","component":"text-input","title":"NIK anak","label":"NIK anak","helpText":"Isi 16 digit angka sesuai KK atau kartu identitas anak.","placeholder":"16 digit NIK anak","required":true,"isActive":true,"choices":[],"colSpan":1,"disabled":false},{"id":"childBirthDate","type":"DATE","component":"calendar","title":"Tanggal lahir anak","label":"Tanggal lahir anak","helpText":"Pilih tanggal lahir anak pada kalender.","placeholder":"","required":true,"isActive":true,"choices":[],"colSpan":1,"disabled":false},{"id":"childSex","type":"LIST","component":"select","title":"Jenis kelamin anak","label":"Jenis kelamin anak","helpText":"","placeholder":"","required":true,"isActive":true,"choices":["Laki-laki","Perempuan"],"colSpan":1,"disabled":false,"dataSource":{"type":"catalog","key":"child_sexes"}},{"id":"parentPhone","type":"TEXT","component":"text-input","title":"Nomor HP orang tua/wali","label":"Nomor HP","helpText":"Nomor aktif yang dapat dihubungi untuk konfirmasi jadwal.","placeholder":"Contoh: 081234567890","required":true,"isActive":true,"choices":[],"colSpan":"full","disabled":false}]},{"id":"parentIdentity","title":"Data Orang Tua & Alamat","description":"Isi data orang tua/wali dan alamat domisili tempat tinggal anak.","fields":[{"id":"fatherName","type":"TEXT","component":"text-input","title":"Nama Ayah","label":"Nama ayah","helpText":"Isi nama ayah kandung/wali sesuai KK.","placeholder":"Nama lengkap ayah/wali","required":true,"isActive":true,"choices":[],"colSpan":1,"disabled":false},{"id":"motherName","type":"TEXT","component":"text-input","title":"Nama Ibu","label":"Nama ibu","helpText":"Isi nama ibu kandung sesuai KK.","placeholder":"Nama lengkap ibu kandung","required":true,"isActive":true,"choices":[],"colSpan":1,"disabled":false},{"id":"childAddress","type":"PARAGRAPH","component":"textarea","title":"Alamat tempat tinggal","label":"Alamat","helpText":"Tuliskan alamat domisili tempat tinggal anak saat ini.","placeholder":"Tuliskan alamat domisili lengkap...","required":true,"isActive":true,"choices":[],"colSpan":"full","disabled":false}]},{"id":"vaccineGateway","title":"Riwayat Vaksinasi Anak","description":"Informasi ini membantu dokter/petugas mengetahui status vaksinasi si kecil.","fields":[{"id":"hasVaccineHistory","type":"MULTIPLE_CHOICE","component":"choice-chips","title":"Apakah si kecil pernah mendapat imunisasi sebelumnya?","label":"Pernah imunisasi","helpText":"","placeholder":"","required":true,"isActive":true,"choices":["Ya, pernah","Belum pernah sama sekali"],"colSpan":"full","disabled":false}]},{"id":"vaccineHistory","title":"Daftar Riwayat Vaksinasi Anak","description":"Pilih status pemberian vaksin yang diingat atau sesuai catatan Buku KIA.","fields":[]},{"id":"allergyHistory","title":"Riwayat Alergi Anak","description":"Informasi riwayat alergi obat, makanan, atau vaksin untuk keselamatan si kecil.","fields":[{"id":"hasAllergyHistory","type":"MULTIPLE_CHOICE","component":"choice-chips","title":"Apakah anak memiliki riwayat alergi?","label":"Ada alergi","helpText":"","placeholder":"","required":true,"isActive":true,"choices":["Tidak ada alergi","Ada riwayat alergi"],"colSpan":"full","disabled":false},{"id":"childAllergyHistory","type":"PARAGRAPH","component":"textarea","title":"Detail riwayat alergi anak","label":"Riwayat alergi","helpText":"Tuliskan jika anak memiliki riwayat alergi obat, makanan, vaksin, atau hal lain.","placeholder":"Contoh: Alergi antibiotik, alergi telur, atau hal lain...","required":false,"isActive":true,"choices":[],"colSpan":"full","disabled":false}]}]}'::jsonb
)
