INSERT INTO clinical_intake_forms (code, name, description, icon_name, is_active, schema)
VALUES (
  'general',
  'Anamnesis Umum',
  'Formulir pengkajian data medis klinis, riwayat kesehatan, tanda-tanda vital, dan keluhan umum pasien saat konsultasi dokter.',
  'stethoscope',
  true,
  '{"version":1,"title":"Formulir Anamnesis Dewasa & Umum","description":"Formulir pengkajian data medis klinis, riwayat kesehatan, tanda-tanda vital, dan keluhan umum pasien.","steps":[{"id":"general_identity","title":"Identitas & Keluhan Utama","description":"Lengkapi data identitas dan keluhan yang dirasakan saat ini.","fields":[{"id":"patient_name","type":"TEXT","component":"text-input","title":"Nama Lengkap Pasien","label":"Nama Lengkap","placeholder":"Masukkan nama lengkap sesuai identitas","helpText":"Nama lengkap tanpa singkatan","required":true,"isActive":true,"colSpan":1},{"id":"patient_nik","type":"TEXT","component":"text-input","title":"Nomor Induk Kependudukan (NIK)","label":"NIK","placeholder":"16 digit angka sesuai KTP / KK","helpText":"16 angka sesuai KTP","required":false,"isActive":true,"colSpan":1},{"id":"patient_birth_date","type":"DATE","component":"calendar","title":"Tanggal Lahir","label":"Tanggal Lahir","placeholder":"Pilih tanggal lahir","helpText":"Tanggal lahir pasien","required":true,"isActive":true,"colSpan":"full"},{"id":"patient_gender","type":"LIST","component":"select","title":"Jenis Kelamin","label":"Jenis Kelamin","helpText":"Pilih jenis kelamin","required":true,"isActive":true,"choices":["Laki-laki","Perempuan"],"dataSource":{"type":"catalog","key":"child_sexes"},"colSpan":1},{"id":"patient_phone","type":"TEXT","component":"text-input","title":"Nomor WhatsApp / Telepon","label":"No. WhatsApp","placeholder":"08xxxxxxxxxx","helpText":"Nomor kontak aktif untuk jadwal dan antrean","required":true,"isActive":true,"colSpan":1},{"id":"chief_complaint","type":"PARAGRAPH","component":"textarea","title":"Keluhan Utama Saat Ini","label":"Keluhan Utama","placeholder":"Jelaskan gejala atau keluhan yang dialami secara singkat...","helpText":"Contoh: demam 3 hari, batuk, pusing, dsb.","required":true,"isActive":true,"colSpan":"full"}]},{"id":"general_history","title":"Riwayat Kesehatan & Pengobatan","description":"Riwayat alergi, penyakit terdahulu, dan konsumsi obat rutin.","fields":[{"id":"has_allergy","type":"MULTIPLE_CHOICE","component":"choice-chips","title":"Apakah Pasien Memiliki Riwayat Alergi Obat / Makanan?","label":"Riwayat Alergi","helpText":"Pilih salah satu","required":true,"isActive":true,"choices":["Tidak Ada","Ada Alergi"],"colSpan":"full"},{"id":"allergy_details","type":"PARAGRAPH","component":"textarea","title":"Rincian Alergi (Jika Ada)","label":"Rincian Alergi","placeholder":"Tuliskan jenis alergi obat/makanan jika ada...","helpText":"Kosongkan jika tidak ada alergi","required":false,"isActive":true,"colSpan":"full"},{"id":"chronic_disease","type":"PARAGRAPH","component":"textarea","title":"Riwayat Penyakit Terdahulu / Kronis","label":"Riwayat Penyakit","placeholder":"Contoh: Hipertensi, Asma, Diabetes, Maag, dll.","helpText":"Tuliskan penyakit yang pernah/sedang diderita","required":false,"isActive":true,"colSpan":"full"},{"id":"current_medication","type":"PARAGRAPH","component":"textarea","title":"Obat-obatan yang Sedang Dikonsumsi","label":"Obat Rutin","placeholder":"Tuliskan nama obat dan dosis jika sedang mengonsumsi obat...","helpText":"Tulis Tidak ada jika tidak mengonsumsi obat rutin","required":false,"isActive":true,"colSpan":"full"}]},{"id":"general_vital_signs","title":"Tanda-Tanda Vital & Catatan Awal","description":"Hasil pengukuran tanda-tanda vital awal jika telah diperiksa.","fields":[{"id":"blood_pressure","type":"TEXT","component":"text-input","title":"Tekanan Darah (mmHg)","label":"Tekanan Darah","placeholder":"Contoh: 120/80","helpText":"Tekanan darah sistolik/diastolik","required":false,"isActive":true,"colSpan":1},{"id":"body_temperature","type":"TEXT","component":"text-input","title":"Suhu Tubuh (°C)","label":"Suhu (°C)","placeholder":"Contoh: 36.5","helpText":"Suhu tubuh dalam Celsius","required":false,"isActive":true,"colSpan":1},{"id":"body_weight","type":"TEXT","component":"text-input","title":"Berat Badan (kg)","label":"Berat Badan (kg)","placeholder":"Contoh: 60","helpText":"Berat badan dalam kg","required":false,"isActive":true,"colSpan":1},{"id":"body_height","type":"TEXT","component":"text-input","title":"Tinggi Badan (cm)","label":"Tinggi Badan (cm)","placeholder":"Contoh: 165","helpText":"Tinggi badan dalam cm","required":false,"isActive":true,"colSpan":1},{"id":"additional_notes","type":"PARAGRAPH","component":"textarea","title":"Catatan Tambahan Tenaga Medis","label":"Catatan Tambahan","placeholder":"Catatan khusus untuk dokter/perawat...","helpText":"Informasi tambahan yang perlu diketahui dokter","required":false,"isActive":true,"colSpan":"full"}]}]}'::jsonb
)
